import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs"
import { basename, join } from "node:path"

const root = join(import.meta.dir, "..")
export const skillsDir = join(root, "images/opencode/seed/skills")
export const agentsPath = join(root, "images/opencode/seed/AGENTS.md")

const START =
  "<!-- skills:auto:start — generated by scripts/gen-agents.ts; do not edit -->"
const END = "<!-- skills:auto:end -->"

type Frontmatter = { name?: string; description?: string }

export function parseFrontmatter(raw: string): Frontmatter {
  const match = /^---\n([\s\S]*?)\n---/.exec(raw)
  if (!match) return {}
  const out: Record<string, string> = {}
  const lines = match[1].split("\n")
  for (let i = 0; i < lines.length; i++) {
    const kv = /^([\w-]+):\s*(.*)$/.exec(lines[i])
    if (!kv) continue
    const key = kv[1]
    let value = kv[2]
    if (/^[>|][+-]?[0-9]*$/.test(value.trim())) {
      const parts: string[] = []
      while (i + 1 < lines.length && /^\s+\S/.test(lines[i + 1])) {
        parts.push(lines[++i].trim())
      }
      value = parts.join(" ")
    } else {
      value = value.trim().replace(/^["'](.*)["']$/, "$1")
    }
    out[key] = value
  }
  return out
}

export function indexDescription(desc: string): string {
  let d = desc.replace(/\s+/g, " ").trim()
  const triggers = d.indexOf(" Triggers -")
  if (triggers !== -1) d = d.slice(0, triggers)
  if (d.length > 240) d = `${d.slice(0, 240).replace(/\s+\S*$/, "")}…`
  return d
}

export function buildIndex(dir = skillsDir): string {
  const skills: { name: string; description: string }[] = []
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue
    const path = join(dir, entry.name, "SKILL.md")
    if (!existsSync(path)) continue
    const fm = parseFrontmatter(readFileSync(path, "utf8"))
    if (!fm.name) continue
    skills.push({ name: fm.name, description: fm.description ?? "" })
  }
  return skills
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((s) => `- \`${s.name}\` — ${indexDescription(s.description)}`)
    .join("\n")
}

export function renderAgents(current: string, dir = skillsDir): string {
  const start = current.indexOf(START)
  const end = current.indexOf(END)
  if (start === -1 || end === -1 || end < start) {
    throw new Error(`seed AGENTS.md is missing the ${START} / ${END} markers`)
  }
  return `${current.slice(0, start + START.length)}\n${buildIndex(dir)}\n${current.slice(end)}`
}

function main() {
  const current = readFileSync(agentsPath, "utf8")
  const next = renderAgents(current)
  if (process.argv.includes("--check")) {
    if (next !== current) {
      const missing = buildIndex()
        .split("\n")
        .filter((l) => !current.includes(l))
      console.error(
        `seed AGENTS.md skills index is stale; run \`bun run gen:agents\`. Missing:\n${missing.join("\n")}`,
      )
      process.exit(1)
    }
    console.log("seed AGENTS.md skills index is fresh")
    return
  }
  if (next !== current) {
    writeFileSync(agentsPath, next)
    console.log(`rewrote ${basename(agentsPath)} skills index`)
  } else {
    console.log("seed AGENTS.md skills index already fresh")
  }
}

if (import.meta.main) main()
